import { getHexagonLinesBisect } from './get-hexagon-lines-bisect.js';
import { getHexagonVertexes } from './get-hexagon-vertexes.js';
import { XyPosition } from '../types/xy-position.js';

export const getHexagonGeometry = (x: number, y: number, width: number) => {
  const hexagonVertexes = getHexagonVertexes(x, y, width);
  const hexagonLinesBisect = getHexagonLinesBisect(hexagonVertexes);

  const hexagonGeometry: XyPosition[] = [];

  for (let i = 0; i < 6; i++) {
    hexagonGeometry.push(hexagonVertexes[i]);
    hexagonGeometry.push(hexagonLinesBisect[i]);
  }

  // We need to close the path rounding the initial point as well.
  hexagonGeometry.push(hexagonVertexes[0]);
  hexagonGeometry.push(hexagonLinesBisect[0]);

  return hexagonGeometry;
};
